//! HTTP server: embedded web UI, JSON light API and OTA upload.

use std::{thread, time::Duration};

use anyhow::bail;
use esp_idf_svc::{
    hal::reset,
    http::{
        server::{Configuration, EspHttpConnection, EspHttpServer, Request},
        Method,
    },
    io::Write,
    ota::EspOta,
};
use protocol::{DeviceInfo, LightState, API_INFO, API_OTA, API_STATE};

use crate::led::Light;

struct Asset {
    path: &'static str,
    mime: &'static str,
    /// gzip-compressed file contents.
    body: &'static [u8],
}

/// Generated by `build.rs` from `web/dist`.
static ASSETS: &[Asset] = include!(concat!(env!("OUT_DIR"), "/assets.rs"));

/// Upper bound for JSON request bodies.
const MAX_JSON_BODY: usize = 256;

type Req<'a, 'r> = Request<&'a mut EspHttpConnection<'r>>;

/// Starts the server. The returned handle must be kept alive.
pub fn start(light: Light, info: DeviceInfo) -> anyhow::Result<EspHttpServer<'static>> {
    let mut server = EspHttpServer::new(&Configuration {
        stack_size: 10 * 1024,
        ..Default::default()
    })?;

    for asset in ASSETS {
        server.fn_handler(asset.path, Method::Get, move |req| serve_asset(req, asset))?;
    }
    let index = ASSETS
        .iter()
        .find(|a| a.path == "/index.html")
        .expect("build.rs checks for index.html");
    server.fn_handler("/", Method::Get, move |req| serve_asset(req, index))?;

    let l = light.clone();
    server.fn_handler(API_STATE, Method::Get, move |req| send_json(req, &l.get()))?;
    server.fn_handler(API_STATE, Method::Put, move |mut req| {
        let body = read_json_body(&mut req)?;
        match serde_json::from_slice::<LightState>(&body) {
            Ok(state) => {
                light.set(state);
                send_json(req, &state)
            }
            Err(e) => send_error(req, 400, &e.to_string()),
        }
    })?;
    server.fn_handler(API_INFO, Method::Get, move |req| send_json(req, &info))?;
    server.fn_handler(API_OTA, Method::Post, |req| match receive_firmware(req) {
        Ok(()) => {
            // Give the response time to reach the browser before rebooting.
            thread::spawn(|| {
                thread::sleep(Duration::from_secs(1));
                reset::restart();
            });
            Ok(())
        }
        Err(e) => {
            log::error!("OTA failed: {e:#}");
            Err(e)
        }
    })?;

    Ok(server)
}

fn serve_asset(req: Req, asset: &Asset) -> anyhow::Result<()> {
    req.into_response(
        200,
        None,
        &[
            ("Content-Type", asset.mime),
            ("Content-Encoding", "gzip"),
            // Assets change with every OTA update and have no content hash in their names.
            ("Cache-Control", "no-cache"),
        ],
    )?
    .write_all(asset.body)?;
    Ok(())
}

fn send_json(req: Req, value: &impl serde::Serialize) -> anyhow::Result<()> {
    req.into_response(200, None, &[("Content-Type", "application/json")])?
        .write_all(&serde_json::to_vec(value)?)?;
    Ok(())
}

fn send_error(req: Req, status: u16, message: &str) -> anyhow::Result<()> {
    req.into_status_response(status)?
        .write_all(message.as_bytes())?;
    Ok(())
}

fn read_json_body(req: &mut Req) -> anyhow::Result<Vec<u8>> {
    let mut body = Vec::new();
    let mut buf = [0; 64];
    loop {
        let n = req.read(&mut buf)?;
        if n == 0 {
            return Ok(body);
        }
        body.extend_from_slice(&buf[..n]);
        if body.len() > MAX_JSON_BODY {
            bail!("request body larger than {MAX_JSON_BODY} bytes");
        }
    }
}

/// Streams the request body into the inactive OTA slot and marks it for the next boot.
/// On any error the partially written update is dropped, which aborts it.
fn receive_firmware(mut req: Req) -> anyhow::Result<()> {
    let mut ota = EspOta::new()?;
    let mut update = ota.initiate_update()?;

    let mut buf = vec![0; 4096];
    let mut total = 0;
    loop {
        let n = req.read(&mut buf)?;
        if n == 0 {
            break;
        }
        update.write(&buf[..n])?;
        total += n;
    }
    if total == 0 {
        bail!("empty firmware image");
    }
    // Validates the image (magic, checksum, hash) before switching the boot partition.
    update.complete()?;

    log::info!("OTA image received ({total} bytes), rebooting");
    req.into_ok_response()?.write_all(b"ok")?;
    Ok(())
}
